	log := NewAuditLog()

	entry := log.Append("key1", "KV.Set", "success")
	if entry.Seq != 1 {
		t.Errorf("Expected seq 1, got %d", entry.Seq)
	}

	if entry.KeyID != "key1" || entry.Method != "KV.Set" {
