	log := NewAuditLog()

	log.Append("key1", "KV.Set", "success")
	log.Append("key2", "KV.Get", "success")

	// Tamper with first entry
	entries := log.Entries()
	if len(entries) > 0 {
		entries[0].Method = "Tampered"
