	policy.AddRule(&PolicyRule{
		Name:    "allow_read",
		Methods: []string{"KV.Get"},
		Effect:  EffectAllow,
	})
	policy.AddRule(&PolicyRule{
		Name:    "deny_write",
		Methods: []string{"KV.Set", "KV.Delete"},
		Effect:  EffectDeny,
	})

	if err := ValidatePolicy(policy); err != nil {
