func TestAuditLogHashChain(t *testing.T) {
	log := NewAuditLog()

	e1 := log.Append("key1", "Method1", "success")
	e2 := log.Append("key2", "Method2", "success")

	if !bytesEqual(e2.PrevHash, e1.Hash) {
