	result := make([]string, 0, len(r.nodeSet))
	for nodeID := range r.nodeSet {
		result = append(result, nodeID)
	}
	return result
}

// hash computes a deterministic uint32 from a string using SHA-256,
// then truncates to the first 4 bytes (big-endian).
func (r *Ring) hash(data string) uint32 {
	sum := sha256.Sum256([]byte(data))
	return binary.BigEndian.Uint32(sum[:4])
}

