	argsBuf := make([]byte, 0, 256)
	var err error
	argsBuf, err = c.codec.Marshal(args, argsBuf)
	if err != nil {
		return fmt.Errorf("marshal args: %w", err)
	}

	// Build request message.
	c.mu.Lock()
	msgID := c.nextID
	c.nextID++
	c.mu.Unlock()

	req := Message{
		Type:   MsgRequest,
		ID:     msgID,
		Method: []byte(method),
		Body:   argsBuf,
	}

	// Register pending response handler.
	c.mu.Lock()
	pend := &pending{ch: make(chan *Message, 1)}
	c.inflight[msgID] = pend
	c.mu.Unlock()

	// Send request.
	reqBuf := make([]byte, 0, HeaderSize+len(method)+len(argsBuf))
	reqBuf = req.Encode(reqBuf)

	c.writeMu.Lock()
	_, err = c.transport.Write(reqBuf)
	c.writeMu.Unlock()

	if err != nil {
		c.mu.Lock()
		delete(c.inflight, msgID)
		c.mu.Unlock()
		return fmt.Errorf("write request: %w", err)
	}

	// Wait for response with optional timeout.
	var respMsg *Message
	if d > 0 {
		select {
		case respMsg = <-pend.ch:
		case <-time.After(d):
			c.mu.Lock()
			delete(c.inflight, msgID)
			c.mu.Unlock()
			return ErrTimeout
